<?php
namespace App\Http\Controllers;
use Illuminate\Http\Request;use App\Models\{Expense,User};use App\Http\Requests\{CreateExpenseRequest,UpdateExpenseRequest};use App\Services\{GroupService,ExpenseService};use App\Support\ApiResponse;
class ExpenseController extends Controller { public function __construct(private GroupService $groups,private ExpenseService $expenses,private ApiResponse $response){} public function index(Request $r,string $group){$g=$this->groups->get($group,$r->user());$q=Expense::where('group_id',(string)$g->_id);if($r->filled('payer'))$q->where('paid_by',$r->payer);if($r->filled('split_type'))$q->where('split_type',$r->split_type);if($r->filled('date_from'))$q->where('created_at','>=',$r->date_from);if($r->filled('date_to'))$q->where('created_at','<=',$r->date_to);$items=$q->orderBy('created_at','desc')->paginate((int)$r->query('per_page',20));return $this->response->success('Expenses retrieved successfully.',$items);} public function store(CreateExpenseRequest $r,string $group){$g=$this->groups->get($group,$r->user());return $this->response->success('Expense created successfully.',$this->expenses->create($r->validated(),$g,$r->user()),201);} public function show(Request $r,string $expense){$e=Expense::findOrFail($expense);$this->groups->get((string)$e->group_id,$r->user());return $this->response->success('Expense retrieved successfully.',$e);} public function update(UpdateExpenseRequest $r,string $expense){$e=Expense::findOrFail($expense);$g=$this->groups->get((string)$e->group_id,$r->user());return $this->response->success('Expense updated successfully.',$this->expenses->update($e,$r->validated(),$g,$r->user()));} public function destroy(Request $r,string $expense){$e=Expense::findOrFail($expense);$this->groups->get((string)$e->group_id,$r->user());$e->delete();return $this->response->success('Expense deleted successfully.');} }
